#!/usr/bin/env bash
# Points git at the hooks folder this file sits in, then seeds the user-level leak-guard pattern
# file (tier 2 of leak-guard.sh) with literals derivable from this machine:
# sibling project directory names, hostname, and username. Non-derivable
# literals (fleet codenames, LAN IPs, internal hostnames) must be added by
# hand afterwards - the generated file says so.
#
# Runs from the package.json `prepare` script. Exits silently if the file
# already exists; never overwrites. The generated file lives outside the
# repo and must never be committed.
#
# smokestack owns this file and delivers it with `bun run shared-core:write`. Change it in
# smokestack; every repository that takes it holds a byte-identical copy.
set -euo pipefail

# core.hooksPath is a clone's own setting, not part of the repository, so every clone needs it set
# and `prepare` is the step every clone runs. It is set to this file's folder (scripts/smokestack/
# hooks, or .githooks in smokestack itself) only where it is unset with no live hook in .git/hooks,
# or names .githooks: that is the folder a repository keeps its own hooks in, which the delivered
# hooks run in turn. Any other value is another tool's dispatch and is left alone, as the installers
# leave it. Nothing here can fail the install.
set_hooks_path() {
	local rel current live
	# Asked of git from inside the folder: two spellings of one path (a mount, a drive letter) never
	# compare equal as strings, and git answers relative to the top of the working tree either way.
	rel="$(cd "$(dirname "$0")" && git rev-parse --show-prefix 2>/dev/null)" || return 0
	rel="${rel%/}"
	[ -n "$rel" ] || return 0
	current="$(git config --local --get core.hooksPath 2>/dev/null || true)"
	case "${current%/}" in
	"$rel" | "./$rel") return 0 ;;
	'' | .githooks | ./.githooks) ;;
	*)
		echo "leak-guard: core.hooksPath is '$current'; not pointing it at $rel." >&2
		return 0
		;;
	esac
	if [ -z "$current" ]; then
		live="$(find "$(git rev-parse --git-path hooks)" -maxdepth 1 -type f ! -name '*.sample' 2>/dev/null | head -n 1 || true)"
		if [ -n "$live" ]; then
			echo "leak-guard: .git/hooks holds live hooks; not pointing core.hooksPath at $rel." >&2
			return 0
		fi
	elif [ "$rel" != .githooks ]; then
		# A delivered hook runs only the repository's own hook of the same name, so leaving .githooks
		# while it holds a hook of any other name would stop that hook running. The names are
		# lib/shared-core/git-hooks.ts GIT_HOOKS.
		local top name orphans=''
		top="$(git rev-parse --show-toplevel)"
		for name in applypatch-msg commit-msg fsmonitor-watchman p4-changelist p4-post-changelist \
			p4-pre-submit p4-prepare-changelist post-applypatch post-checkout post-commit \
			post-index-change post-merge post-rewrite pre-applypatch pre-auto-gc pre-commit \
			pre-merge-commit pre-push pre-rebase prepare-commit-msg push-to-checkout \
			reference-transaction sendemail-validate; do
			if [ -f "$top/.githooks/$name" ] && [ ! -f "$top/$rel/$name" ]; then
				orphans="$orphans .githooks/$name"
			fi
		done
		if [ -n "$orphans" ]; then
			echo "leak-guard: .githooks holds$orphans, which no delivered hook runs; not pointing core.hooksPath at $rel." >&2
			return 0
		fi
	fi
	git config --local core.hooksPath "$rel" && echo "leak-guard: core.hooksPath set to $rel" >&2
	return 0
}
set_hooks_path

# Resolved exactly as leak-guard.sh resolves it, or a process that predates the Windows
# user-level variable would seed a second, weaker file at the default path.
target="${LEAK_GUARD_PATTERNS:-}"
if [ -z "$target" ] && command -v reg.exe >/dev/null 2>&1; then
	target="$(MSYS_NO_PATHCONV=1 reg.exe query 'HKCU\Environment' /v LEAK_GUARD_PATTERNS 2>/dev/null |
		tr -d '\r' | sed -nE 's/^[[:space:]]*LEAK_GUARD_PATTERNS[[:space:]]+REG_(EXPAND_)?SZ[[:space:]]+//p' || true)"
fi
target="${target:-$HOME/.config/leak-guard/patterns}"
[ -f "$target" ] && exit 0

# Names that are public (or dot-dirs) and must not become private literals.
is_public() {
	case "$1" in
	aidd | spernakit | starsync | node_modules | .*) return 0 ;;
	esac
	return 1
}

escape_ere() {
	printf '%s' "$1" | sed 's/[][\.|$(){}?+*^]/\\&/g'
}

repo_root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
workspace="$(dirname "$repo_root")"

mkdir -p "$(dirname "$target")"
{
	echo '# leak-guard private patterns (extended regex, one per line; # = comment).'
	echo '# Tier 2 of leak-guard.sh - never commit this file.'
	echo '# Generated by leak-guard-setup.sh from workspace directory'
	echo '# names, hostname, and username. REVIEW IT and add non-derivable'
	echo '# literals by hand: fleet codenames, LAN IPs, internal hostnames.'
	for dir in "$workspace"/*/; do
		[ -d "$dir" ] || continue
		name="$(basename "$dir")"
		is_public "$name" && continue
		# Very short names (ai, g5, ...) collide with ordinary prose; add
		# them by hand only if they are genuinely private.
		[ "${#name}" -lt 4 ] && continue
		printf '\\b%s\\b\n' "$(escape_ere "$name")"
	done
	host="$(hostname 2>/dev/null || true)"
	if [ -n "$host" ]; then
		printf '\\b%s\\b\n' "$(escape_ere "$host")"
	fi
	user_name="${USERNAME:-${USER:-}}"
	if [ -n "$user_name" ]; then
		printf '\\b%s\\b\n' "$(escape_ere "$user_name")"
	fi
} >"$target"

echo "leak-guard: generated $target - review it and add fleet codenames / LAN IPs." >&2
exit 0
